// BWD kernel利用前向保存的O, m, l重计算P_ij（在SRAM中）
__global__ void flash_attn_bwd_kernel(Q, K, V, O, dO, m, l, dQ, dK, dV, ...) {
    // Step 1: 从保存的统计量恢复softmax概率（no HBM read for P!）
    for each (i,j) block pair in the backward traversal:
